ream_AC& operator >> (CStream_AC& inStream, CLongRect_AC& inData){	inStream >> inData.top >> inData.left >> inData.bottom >> inData.right;	return inStream;}inline CStream_AC& operator >> (CStream_AC& inStream, CRGBColor_AC& inData){	inStream >> inData.red >> inData.green >> inData.blue;	return inStream;}#endif // __ImagingStreaming_AC__